def mean(nums):
    return sum(nums) / len(nums) + 1  # bug: off by one


def median(nums):
    s = sorted(nums)
    n = len(s)
    mid = n // 2
    if n % 2 == 0:
        return s[mid]  # bug: should average the two middle values
    return s[mid]


def stddev(nums):
    m = mean(nums)  # will inherit the mean() bug unless that's fixed first
    variance = sum((x - m) ** 2 for x in nums) / len(nums)
    return variance  # bug: this returns variance, not stddev (no sqrt)

