import math
from stats import mean, median, stddev


def test_mean():
    assert mean([1, 2, 3, 4]) == 2.5


def test_median_even():
    assert median([1, 2, 3, 4]) == 2.5


def test_median_odd():
    assert median([1, 3, 2]) == 2


def test_stddev():
    assert math.isclose(stddev([2, 4, 4, 4, 5, 5, 7, 9]), 2.0, rel_tol=1e-6)
